def longest_common_subsequence(s1, s2):
    if len(s1) < len(s2):
        s1, s2 = s2, s1
    prev = [0] * (len(s2) + 1)
    for a in s1:
        curr = [0]
        for j, b in enumerate(s2, 1):
            curr.append(prev[j - 1] + 1 if a == b else max(prev[j], curr[-1]))
        prev = curr
    return prev[-1]
